import mammoth from 'mammoth';

/**
 * Microsoft Word (.docx) Academic Parsing Service
 *
 * Extracts clean, readable text, section hierarchy, tables, and metadata
 * from Word manuscripts (.docx).
 * Paginates text (~550 words per page) to integrate seamlessly with
 * Papermind's page-grounded RAG, vector embedding, and citation features.
 */

/**
 * Clean HTML generated by Mammoth into structured plain text
 */
const htmlToStructuredText = (html) => {
  let text = html;

  // 1. Structure headings
  text = text.replace(/<h1[^>]*>([\s\S]*?)<\/h1>/gi, '\n\n=== SECTION: $1 ===\n\n');
  text = text.replace(/<h2[^>]*>([\s\S]*?)<\/h2>/gi, '\n\n=== SECTION: $1 ===\n\n');
  text = text.replace(/<h3[^>]*>([\s\S]*?)<\/h3>/gi, '\n\n--- SUBSECTION: $1 ---\n\n');
  text = text.replace(/<h[4-6][^>]*>([\s\S]*?)<\/h[4-6]>/gi, '\n\n[ $1 ]\n\n');

  // 2. Structure tables
  text = text.replace(/<tr[^>]*>([\s\S]*?)<\/tr>/gi, (match, rowContent) => {
    const cells = [];
    const cellRegex = /<(?:td|th)[^>]*>([\s\S]*?)<\/(?:td|th)>/gi;
    let cellMatch;
    while ((cellMatch = cellRegex.exec(rowContent)) !== null) {
      cells.push(cellMatch[1].replace(/<[^>]+>/g, '').trim());
    }
    return cells.length > 0 ? `\n| ${cells.join(' | ')} |` : '';
  });
  text = text.replace(/<\/?table[^>]*>/gi, '\n');

  // 3. Structure list items
  text = text.replace(/<li[^>]*>([\s\S]*?)<\/li>/gi, '\n• $1');
  text = text.replace(/<\/?(?:ul|ol)[^>]*>/gi, '\n');

  // 4. Structure paragraphs & breaks
  text = text.replace(/<br\s*\/?>/gi, '\n');
  text = text.replace(/<p[^>]*>([\s\S]*?)<\/p>/gi, '\n\n$1\n\n');

  // 5. Remove remaining HTML tags
  text = text.replace(/<[^>]+>/g, '');

  // 6. Decode common HTML entities
  text = text
    .replace(/&amp;/g, '&')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&quot;/g, '"')
    .replace(/&#39;/g, "'")
    .replace(/&nbsp;/g, ' ');

  // 7. Clean excessive whitespace
  text = text.replace(/[ \t]+/g, ' ');
  text = text.replace(/\n{3,}/g, '\n\n');

  return text.trim();
};

/**
 * Extract candidate title from Word document
 */
export const extractDocxTitle = (html, rawText) => {
  // 1. Try to find first <h1> or <h2> tag
  const headingMatch = html.match(/<h[12][^>]*>([\s\S]*?)<\/h[12]>/i);
  if (headingMatch && headingMatch[1]) {
    const cleanHeading = headingMatch[1].replace(/<[^>]+>/g, '').trim();
    if (cleanHeading.length >= 5 && cleanHeading.length <= 250) {
      return cleanHeading;
    }
  }

  // 2. Fallback: inspect the first few non-empty paragraphs
  const paragraphs = rawText.split(/\n+/).map(p => p.trim()).filter(Boolean);
  for (let i = 0; i < Math.min(paragraphs.length, 5); i++) {
    const p = paragraphs[i];
    // Skip common headers/metadata lines
    const lower = p.toLowerCase();
    if (
      lower.startsWith('abstract') ||
      lower.startsWith('keywords') ||
      lower.startsWith('author') ||
      lower.startsWith('doi:') ||
      lower.startsWith('issn:') ||
      p.length < 6 ||
      p.length > 250
    ) {
      continue;
    }
    return p;
  }

  return null;
};

/**
 * Extract candidate authors from Word document
 */
export const extractDocxAuthors = (rawText, extractedTitle) => {
  const paragraphs = rawText.split(/\n+/).map(p => p.trim()).filter(Boolean);
  if (paragraphs.length === 0) return [];

  let titleIndex = -1;
  if (extractedTitle) {
    titleIndex = paragraphs.findIndex(p => p.toLowerCase().includes(extractedTitle.toLowerCase().slice(0, 30)));
  }

  const startIdx = titleIndex >= 0 ? titleIndex + 1 : 0;
  const candidates = [];

  for (let i = startIdx; i < Math.min(paragraphs.length, startIdx + 4); i++) {
    const p = paragraphs[i];
    const lower = p.toLowerCase();

    // Stop searching once we reach abstract or introduction
    if (lower.startsWith('abstract') || lower.startsWith('1. introduction') || lower.startsWith('introduction')) {
      break;
    }

    // Ignore affiliations / emails / disclaimers
    if (
      lower.includes('university') ||
      lower.includes('department') ||
      lower.includes('institute') ||
      lower.includes('@') ||
      lower.includes('http') ||
      lower.includes('correspondence')
    ) {
      continue;
    }

    // Check if line looks like author names
    const cleanedLine = p.replace(/^(authors?|by)[:\s]*/i, '').trim();
    const parts = cleanedLine.split(/,| and | & |;/).map(a => a.trim()).filter(a => a.length >= 2 && a.length <= 50);

    if (parts.length > 0 && parts.length <= 10) {
      for (const part of parts) {
        if (!part.includes('@') && !part.match(/\d{4}/)) {
          candidates.push(part);
        }
      }
      if (candidates.length > 0) break;
    }
  }

  return [...new Set(candidates)];
};

/**
 * Paginate clean Word document text into structured pages (~550 words per page)
 */
export const paginateDocx = (cleanText, wordsPerPage = 550) => {
  if (!cleanText || cleanText.trim().length === 0) {
    return [{ pageNumber: 1, text: 'Empty document content.' }];
  }

  const paragraphs = cleanText.split(/\n\n+/);
  const pages = [];
  let currentPageWords = [];
  let pageNumber = 1;

  for (const para of paragraphs) {
    const paraWords = para.split(/\s+/).filter(Boolean);

    if (currentPageWords.length > 0 && (currentPageWords.length + paraWords.length) > wordsPerPage) {
      pages.push({
        pageNumber,
        text: currentPageWords.join(' '),
      });
      pageNumber++;
      currentPageWords = [];
    }

    currentPageWords.push(para);
  }

  if (currentPageWords.length > 0) {
    pages.push({
      pageNumber,
      text: currentPageWords.join(' '),
    });
  }

  return pages.length > 0 ? pages : [{ pageNumber: 1, text: cleanText }];
};

/**
 * Main parser entry point for .docx file buffers
 */
export const extractDocxText = async (buffer) => {
  if (!buffer || buffer.length === 0) {
    throw new Error('Word (.docx) file buffer is empty.');
  }

  // Convert to HTML to preserve structure and formatting
  const htmlResult = await mammoth.convertToHtml({ buffer });
  const rawResult = await mammoth.extractRawText({ buffer });

  const html = htmlResult.value || '';
  const rawTextPlain = rawResult.value || '';

  const cleanText = htmlToStructuredText(html || rawTextPlain);

  if (cleanText.length < 50) {
    throw new Error('Word (.docx) document does not contain enough extractable text.');
  }

  const extractedTitle = extractDocxTitle(html, cleanText);
  const extractedAuthors = extractDocxAuthors(cleanText, extractedTitle);
  const pages = paginateDocx(cleanText);

  return {
    rawText: cleanText,
    pages,
    extractedTitle,
    extractedAuthors,
  };
};
